entries[97066] = { ["name"] = "Wildpilz", ["text"] = "11% von Grundmana 40 Meter Reichweite\nSofort\nLässt einen magischen Pilz mit 3 Gesundheit am Zielort wachsen. Nach 6 Sek. wird der Pilz unsichtbar. Wird er vom Druiden ausgelöst, explodieren alle Pilze und fügen allen Gegnern im Umkreis von 8 Metern 323 Naturschaden zu. Es können immer nur 5 Pilze gleichzeitig platziert werden.\n\nNutzt 'Wildpilz: Detonieren', um alle Pilze explodieren zu lassen." }
entries[97067] = { ["name"] = "Hurrikan", ["text"] = "81% von Grundmana 30 Meter Reichweite\nKanalisiert (Wirken in 10 sek.)\nErzeugt einen wütenden Sturm im Zielgebiet, der Feinden alle 1 Sek. 339 Naturschaden zufügt [ Glyphe 'Hurrikan' : ihr Bewegungstempo um 50% verringert / ]und die Zeit zwischen ihren Angriffen um 0% erhöht. Hält 10 Sek. lang an. Ein Druide muss seine Kräfte kanalisieren, um den Zauber aufrechtzuerhalten." }
entries[97068] = { ["name"] = "Tod und Verfall", ["text"] = "1 Unheilige Rune / -10 Runenmacht 30 Meter Reichweite\nSpontanzauber 30 sek. Abklingzeit\nVerderbt den vom Todesritter anvisierten Boden und fügt allen Zielen, die in diesem Bereich bleiben, 10 Sek. lang pro Sekunde [ 51 + (Angriffskraft * 0.064)] Schattenschaden zu. Diese Fähigkeit erzeugt ein hohes Maß an Bedrohung." }
entries[97069] = { ["name"] = "Blizzard", ["text"] = "74% von Grundmana 35 Meter Reichweite\nKanalisiert (Wirken in 8 sek.)\nEisbrocken prasseln auf das Zielgebiet nieder und verursachen 8 Sek. lang insgesamt ( 336 * 8) Frostschaden." }
entries[97070] = { ["name"] = "Flammenstoß", ["text"] = "30% von Grundmana 40 Meter Reichweite\nWirken in 2 sek.\nLässt eine Feuersäule niedergehen, die alle Feinde im Gebiet verbrennt und ihnen zunächst 689 Feuerschaden und zusätzlich im Verlauf von 8 Sek. 48 Feuerschaden zufügt." }
entries[97071] = { ["name"] = "Druckwelle", ["text"] = "7% von Grundmana 40 Meter Reichweite\nSofort 15 sek. Abklingzeit\nEine Flammenwelle geht vom Zaubernden aus. Alle Feinde, die sich im Radius der Flammen befinden, erleiden 1029 Feuerschaden und werden 3 Sek. lang um 70% verlangsamt." }
entries[97073] = { ["name"] = "Feuerregen", ["text"] = "57% von Grundmana 35 Meter Reichweite\nKanalisiert (Wirken in 8 sek.)\nLässt einen feurigen Regen niedergehen, der 6 Sek. lang Gegner im Effektbereich mit insgesamt ( 267 * 4) Feuerschaden verbrennt." }
entries[97074] = { ["name"] = "Ring des Frosts", ["text"] = "7% von Grundmana 30 Meter Reichweite\nSofort 2 min Abklingzeit\nBeschwört im ausgewählten Gebiet einen Frostzirkel, der 2.50 Sek. benötigt, um sich vollständig zu schließen. Gegner, die den vollständig geschlossenen Zirkel betreten, werden 10 Sek. lang eingefroren. Der Zirkel hält 12 Sek. lang an und hat einen Radius von 10 Metern." }
entries[97076] = { ["name"] = "Erdbeben", ["text"] = "60% von Grundmana 35 Meter Reichweite\nWirken in 2.5 sek. 10 sek. Abklingzeit\nIhr lasst die Erde am Zielort beben und brechen. Feinden in einem Umkreis von 8 Metern wird alle 1 Sek. 361 körperlicher Schaden zugefügt, mit einer Chance von 10%, betroffene Ziele umzuwerfen. Hält 10 Sek. lang an." }
